float z = p->pos.z;
float vz = p->vel.z;

float frontWall = h + boxWidth;
float backWall  = h - boxWidth;

if (z >= frontWall) {
    p->pos.z = 2.0f * frontWall - z;
    p->vel.z = -elasticity * vz;
} else if (z <= backWall) {
    p->pos.z = 2.0f * backWall - z;
    p->vel.z = -elasticity * vz;
}
// END_CODE

